source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not twos:
        return out

    # The 2s form a full horizontal or vertical guide line.
    row_counts = [sum(v == 2 for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    horizontal = max(row_counts) == w
    if horizontal:
        guide = row_counts.index(w)
        background = max((v for row in grid for v in row if v != 2), key=lambda v: sum(x == v for row in grid for x in row))
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, background)]
        if not points:
            return out
        lo, hi = min(r for r, c in points), max(r for r, c in points)
        if lo > guide:
            shift = -(lo - guide - 1)
            far = hi + shift + 1
        else:
            shift = guide - hi - 1
            far = lo + shift - 1
        if not (0 <= far < h):
            return out
        # Translate toward the guide until adjacent, then mark the far edge.
        for r, c in points:
            out[r][c] = background
        for r, c in points:
            out[r + shift][c] = grid[r][c]
        for r in range(h):
            out[r][0] = out[r][0]  # no-op; line is horizontal below
        for c in range(w):
            out[far][c] = 8
        return out

    guide = col_counts.index(h)
    background = max((v for row in grid for v in row if v != 2), key=lambda v: sum(x == v for row in grid for x in row))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, background)]
    if not points:
        return out
    left, right = min(c for r, c in points), max(c for r, c in points)
    if left > guide:
        # A distant pattern on the right is echoed into the available gap.
        gap = left - guide - 1
        width = right - left + 1
        if gap == 0:
            line = right + 1
        elif gap >= width + 1:
            shift = guide + 1 - left
            for r, c in points:
                out[r][c + shift] = grid[r][c]
            line = guide + width + 1
        else:
            shift = -gap
            for r, c in points:
                out[r][c] = background
            for r, c in points:
                out[r][c + shift] = grid[r][c]
            line = left + shift - 1
    else:
        gap = guide - right - 1
        if gap == 0:
            line = left - 1
        else:
            shift = gap
            for r, c in points:
                out[r][c] = background
            for r, c in points:
                out[r][c + shift] = grid[r][c]
            line = left + shift - 1
    if 0 <= line < w:
        for r in range(h):
            out[r][line] = 8
    return out
